<script lang="ts">
 import {onMount,tick} from 'svelte';import {Search,Bell,X,GripVertical,ChevronLeft,ChevronRight} from '@lucide/svelte';import {translator} from './i18n';import {commandIcon} from './desktop-icons';import {notificationHistory} from './notification-history';import type {DesktopCommand} from './desktop-menu';
 export let language:'ru'|'ro';export let windows:{id:string;title:string;minimized:boolean}[]=[];export let active='';export let menus:DesktopCommand[];export let onfocus:(id:string)=>void;export let onminimize:(id:string)=>void;export let onclose:(id:string)=>void;export let oncommand:(id:string)=>void;export let position='bottom';
 let locked=true,labels=true,searchMode='icon',query='',panel='',context=false,hover='',timer:ReturnType<typeof setTimeout>,dragging=false,now=new Date(),month=new Date(),contextX=0,contextY=0;
 $:t=translator(language);$:locale=language==='ru'?'ru-RU':'ro-RO';
 function group(id:string){const prefix=id.split(':')[0];return /^(account|open-account|close-account|opening-balances)/.test(prefix)?'accounts':/^(batch|paymentrecord)/.test(prefix)?'payments':/^(meterdoc|physicaleditor|individual|shared)/.test(prefix)?'meters':prefix;}
 $:groups=[...new Set(windows.map(w=>group(w.id)))].map(id=>({id,windows:windows.filter(w=>group(w.id)===id)}));
 function flatten(items:DesktopCommand[],parent=''): {id:string;title:string;group:string}[]{return items.flatMap(item=>item.children?flatten(item.children,item[language]):item.action?[{id:item.action,title:item[language],group:parent}]:[]);}
 $:commands=flatten(menus);$:results=query.trim()?commands.filter(c=>(c.title+' '+c.group).toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())):commands.slice(0,8);
 $:if(hover&&!groups.some(g=>g.id===hover))hover='';
 function save(){localStorage.setItem('openhau-taskbar',JSON.stringify({locked,labels,searchMode,position}));}
 onMount(()=>{try{const x=JSON.parse(localStorage.getItem('openhau-taskbar')||'null');if(x){locked=x.locked!==false;labels=x.labels!==false;if(['hidden','icon','field'].includes(x.searchMode))searchMode=x.searchMode;if(['bottom','top','left','right'].includes(x.position))position=x.position;}}catch{}const interval=setInterval(()=>now=new Date(),1000);return()=>{clearInterval(interval);clearTimeout(timer);};});
 function outside(e:PointerEvent){if(!(e.target instanceof Element)||!e.target.closest('.desktop-taskbar,.taskbar-flyout,.taskbar-menu')){panel='';context=false;hover='';}}
 function showPreview(id:string){clearTimeout(timer);timer=setTimeout(()=>{hover=id;void tick().then(()=>renderPreviews());},220);}
 function leave(){clearTimeout(timer);timer=setTimeout(()=>hover='',180);}
 function renderPreviews(){for(const win of windows.filter(w=>group(w.id)===hover)){const holder=document.getElementById('preview-'+win.id),source=document.getElementById('desktop-'+win.id);if(!holder||!source)continue;const clone=source.cloneNode(true) as HTMLElement;clone.querySelectorAll('iframe,script').forEach(n=>n.remove());clone.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));clone.removeAttribute('id');clone.classList.remove('window-hidden');clone.inert=true;clone.style.cssText=`position:relative;display:flex;left:0;top:0;width:${source.offsetWidth||1000}px;height:${source.offsetHeight||650}px;transform:scale(${180/(source.offsetWidth||1000)});transform-origin:top left;pointer-events:none;`;holder.replaceChildren(clone);}}
 function toggle(id:string){const w=windows.find(w=>w.id===id);if(w&&active===id&&!w.minimized)onminimize(id);else onfocus(id);}
 function stopDrag(e:PointerEvent){if(!dragging)return;dragging=false;const distances=[['left',e.clientX],['right',window.innerWidth-e.clientX],['top',e.clientY],['bottom',window.innerHeight-e.clientY]].sort((a,b)=>Number(a[1])-Number(b[1]));position=String(distances[0][0]);save();}
 function moveMonth(delta:number){month=new Date(month.getFullYear(),month.getMonth()+delta,1);}
 $:days=(()=>{const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7;return Array.from({length:42},(_,i)=>new Date(first.getFullYear(),first.getMonth(),1-offset+i));})();
</script>
<svelte:window onpointerdown={outside} onpointerup={stopDrag} onkeydown={e=>{if(e.key==='Escape'){panel='';context=false;hover='';}}}/>
<footer class="desktop-taskbar" class:vertical={position==='left'||position==='right'} class:icons={!labels} class:dragging oncontextmenu={e=>{e.preventDefault();contextX=Math.min(e.clientX,window.innerWidth-270);contextY=Math.max(0,e.clientY-300);context=true;}} aria-label={t('Панель задач','Bara de activități')}>
 {#if !locked}<button title={t('Перетащить панель к краю','Trageți bara la margine')} onpointerdown={e=>{dragging=true;e.currentTarget.setPointerCapture(e.pointerId);}}><GripVertical size={18}/></button>{/if}
 {#if searchMode!=='hidden'}<button title={t('Поиск пунктов меню','Caută comenzi')} onclick={()=>panel=panel==='search'?'':'search'}><Search size={19}/></button>{#if searchMode==='field'}<input aria-label={t('Поиск','Căutare')} placeholder={t('Поиск','Căutare')} bind:value={query} onfocus={()=>panel='search'}/>{/if}{/if}
 <div class="taskbar-windows">{#each groups as group}{@const Icon=commandIcon({id:group.windows[0].id,ru:'',ro:''})}<div class="taskbar-group" role="group" class:stacked={group.windows.length>1} onpointerenter={()=>showPreview(group.id)} onpointerleave={leave}><button class:active={group.windows.some(w=>w.id===active&&!w.minimized)} data-window-id={group.windows[0].id} title={group.windows[0].title} onclick={()=>{if(group.windows.length===1)toggle(group.windows[0].id);else{hover=group.id;void tick().then(renderPreviews);}}}><Icon size={19}/>{#if labels}<span>{group.windows[0].title}</span>{/if}{#if group.windows.length>1}<small>{group.windows.length}</small>{/if}</button></div>{/each}</div>
 <button class="clock" onclick={()=>{panel=panel==='calendar'?'':'calendar';month=new Date();}}><span>{now.toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit'})}</span><small>{now.toLocaleDateString(locale)}</small></button><button title={t('Центр уведомлений','Centrul de notificări')} onclick={()=>panel=panel==='notifications'?'':'notifications'}><Bell size={19}/>{#if $notificationHistory.length}<small>{$notificationHistory.length}</small>{/if}</button>
</footer>
{#if context}<div class="taskbar-menu" style:left={contextX+'px'} style:top={contextY+'px'}><label><input type="checkbox" bind:checked={locked} onchange={save}/>{t('Закрепить панель задач','Blochează bara')}</label><label><input type="checkbox" bind:checked={labels} onchange={save}/>{t('Значки и заголовки окон','Pictograme și titluri')}</label><label>{t('Поиск','Căutare')}<select bind:value={searchMode} onchange={save}><option value="hidden">{t('Нет','Ascuns')}</option><option value="icon">{t('Только значок','Doar pictogramă')}</option><option value="field">{t('Строка поиска','Câmp de căutare')}</option></select></label><p>{t('Снимите закрепление и перетащите панель за ручку к краю окна.','Deblocați bara și trageți mânerul la marginea ferestrei.')}</p></div>{/if}
{#if hover}<div class="taskbar-flyout previews" role="group" onpointerenter={()=>clearTimeout(timer)} onpointerleave={leave}>{#each windows.filter(w=>group(w.id)===hover) as win}<article><header><span>{win.title}</span><button aria-label={t('Закрыть окно','Închide fereastra')} onclick={()=>onclose(win.id)}><X size={14}/></button></header><button class="preview-button" onclick={()=>{onfocus(win.id);hover='';}}><div class="preview-image" id={'preview-'+win.id} aria-hidden="true"></div><span>{win.minimized?t('Свёрнуто','Minimizat'):t('Открыть окно','Deschide fereastra')}</span></button></article>{/each}</div>{/if}
{#if panel}<aside class="taskbar-flyout side-panel"><header><strong>{panel==='search'?t('Поиск','Căutare'):panel==='calendar'?t('Дата и время','Data și ora'):t('Уведомления','Notificări')}</strong><button aria-label={t('Закрыть','Închide')} onclick={()=>panel=''}><X size={18}/></button></header>
 {#if panel==='search'}<input aria-label={t('Поиск пунктов меню','Caută comenzi')} placeholder={t('Найти команду','Caută o comandă')} bind:value={query}/>{#each results as result}<button class="search-result" onclick={()=>{panel='';oncommand(result.id);}}>{result.title}<small>{result.group}</small></button>{/each}{#if !results.length}<p>{t('Ничего не найдено','Niciun rezultat')}</p>{/if}
 {:else if panel==='calendar'}<div class="large-clock">{now.toLocaleTimeString(locale)}</div><p>{now.toLocaleDateString(locale,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p><div class="month"><button onclick={()=>moveMonth(-1)}><ChevronLeft size={18}/></button><strong>{month.toLocaleDateString(locale,{month:'long',year:'numeric'})}</strong><button onclick={()=>moveMonth(1)}><ChevronRight size={18}/></button></div><div class="calendar">{#each Array.from({length:7},(_,i)=>new Date(2026,9,26+i)) as day}<b>{day.toLocaleDateString(locale,{weekday:'short'})}</b>{/each}{#each days as day}<span class:muted={day.getMonth()!==month.getMonth()} class:today={day.toDateString()===now.toDateString()}>{day.getDate()}</span>{/each}</div>
 {:else}<button onclick={()=>notificationHistory.set([])} disabled={!$notificationHistory.length}>{t('Очистить все','Șterge toate')}</button>{#each $notificationHistory as notification}<article class="history-item"><header><time>{new Date(notification.date).toLocaleString(locale)}</time><button aria-label={t('Удалить уведомление','Elimină notificarea')} onclick={()=>notificationHistory.update(rows=>rows.filter(r=>r.id!==notification.id))}><X size={15}/></button></header><p>{notification.text}</p></article>{/each}{#if !$notificationHistory.length}<p>{t('Новых уведомлений нет','Nu sunt notificări')}</p>{/if}{/if}
</aside>{/if}
<style>
.desktop-taskbar{grid-area:dock;min-width:0;display:flex;align-items:center;gap:5px;padding:4px 8px;z-index:900;background:color-mix(in srgb,var(--sidebar) 90%,transparent);backdrop-filter:blur(22px);min-height:44px}.desktop-taskbar button,.taskbar-flyout button{border:0;background:transparent;color:var(--text);display:flex;align-items:center;justify-content:center;gap:7px;padding:8px}.desktop-taskbar button:hover,.taskbar-flyout button:hover{background:var(--hover)}.taskbar-windows{display:flex;gap:5px;flex:1;min-width:0;overflow:auto;padding:3px}.taskbar-group{position:relative;flex-shrink:0;max-width:220px}.taskbar-group>button{max-width:220px;height:34px}.taskbar-group span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.taskbar-group.stacked{box-shadow:2px 2px 0 var(--muted),4px 4px 0 var(--border);margin-right:5px}.taskbar-group button.active{border-bottom:2px solid var(--accent);background:var(--hover)}.clock{flex-direction:column;gap:0!important;font-size:11px}.clock small{font-size:10px}.vertical{flex-direction:column;width:200px}.vertical .taskbar-windows{flex-direction:column;width:100%}.vertical .taskbar-group>button{width:100%;justify-content:flex-start}.vertical.icons{width:62px}.dragging{outline:2px dashed var(--accent)}.taskbar-menu,.taskbar-flyout{position:fixed;z-index:20000;background:color-mix(in srgb,var(--surface) 95%,transparent);backdrop-filter:blur(24px);box-shadow:0 8px 28px #0005;color:var(--text);padding:16px}.taskbar-menu{width:260px}.taskbar-menu label{display:flex;gap:9px;align-items:center;margin:12px 0}.taskbar-menu select{max-width:150px}.taskbar-menu p{font-size:11px;line-height:1.5}.taskbar-flyout header{display:flex;align-items:center;justify-content:space-between;gap:12px}.side-panel{right:10px;bottom:52px;width:min(380px,calc(100vw - 20px));max-height:75vh;overflow:auto}.side-panel>input{width:100%;margin:12px 0}.search-result{display:flex!important;flex-direction:column;align-items:flex-start!important;width:100%}.search-result small{color:var(--muted)}.previews{left:50%;transform:translateX(-50%);bottom:52px;display:flex;gap:12px;max-width:90vw;overflow:auto;animation:preview-in .15s ease-out}.previews article{width:200px;flex:none}.previews header{font-size:11px}.previews header span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.preview-button{display:block!important;width:100%}.preview-image{width:180px;height:118px;overflow:hidden;background:var(--bg)}.preview-button>span{font-size:10px}.large-clock{font-size:34px;margin-top:18px}.month{display:flex;align-items:center;justify-content:space-between}.calendar{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;gap:4px;margin-top:12px}.calendar span,.calendar b{padding:9px 3px}.calendar .muted{opacity:.4}.calendar .today{background:var(--accent);color:white}.history-item{border-top:1px solid var(--border);margin-top:14px;padding-top:10px}.history-item time{font-size:11px;color:var(--muted)}.history-item p{white-space:pre-wrap;overflow-wrap:anywhere}@keyframes preview-in{from{opacity:0;margin-bottom:-8px}to{opacity:1;margin-bottom:0}}@media(prefers-reduced-motion:reduce){.previews{animation:none}}
</style>
